    ${mjSchema}_rgc.[EntityID] = 'D92AD8CD-F023-4C89-9857-748F4EC2AD20'
    AND ${mjSchema}_rgc.[RecordID] = CAST([e].[ID] AS NVARCHAR(450))
    AND ${mjSchema}_rgc.[LocationType] = 'Primary'
